        int wei = weight[i];
        long wor = worth[i];
        for (int s=0; s<=MAX; s++) {
            dp[i][s] = dp[i-1][s];
        }
        for (int s=0; s<=MAX; s++) {
            if (dp[i-1][s] != -1) {
                if (s + wei <= MAX) {
                    dp[i][s+wei] = Math.max(dp[i][s+wei], dp[i-1][s] + wor);
                }
            }
        }
    }
    long max_worth = 0;
    for (int i=0; i<=MAX; i++) {
        if (max_worth < dp[N-1][i]) {
            max_worth = dp[N-1][i];
        }
    }
    return max_worth;
}

